package main

import (
 "fmt"
 "go/ast"
 "go/importer"
 "go/parser"
 "go/token"
 "go/types"
)
const src=`package a
type Box[T any] struct{}
func (Box[T]) Get() error {return nil}
var A Box[interface{ Close() error }]
var B Box[map[string]*Box[int]]
`
func main(){
 fset:=token.NewFileSet()
 f,_:=parser.ParseFile(fset,"a.go",src,0)
 conf:=types.Config{Importer: importer.Default()}
 pkg,_:=conf.Check("example.com/a",fset,[]*ast.File{f},nil)
 for _,n:=range []string{"A","B"}{
  obj:=pkg.Scope().Lookup(n)
  fmt.Printf("%q\n", types.TypeString(obj.Type(), func(p *types.Package) string { if p==nil {return ""}; return p.Path()}))
 }
}
EOF
