cat > checker.go <<'EOF'
package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

var errorInterface = types.Universe.Lookup("error").Type().Underlying().(*types.Interface)

type UncheckedError struct {
	Pos      token.Position
	Line     string
	FuncName string
}

type Checker struct {
	abspath         bool
	asserts         bool
	blank           bool
	excluded        map[string]bool
	ignore          ignoreFlag
	ignoreGenerated bool
	ignorePkg       string
	ignoreTests     bool
	mod             string
	tags            tagsFlag
	verbose         bool

	cwd      string
	ignorePk map[string]bool
}

func (c *Checker) CheckPackages(patterns []string) ([]UncheckedError, error) {
	if len(patterns) == 0 {
		patterns = []string{"."}
	}
	c.cwd, _ = os.Getwd()

	buildFlags := []string{}
	if len(c.tags) > 0 {
		buildFlags = append(buildFlags, "-tags="+strings.Join([]string(c.tags), " "))
	}
	if c.mod != "" {
		buildFlags = append(buildFlags, "-mod="+c.mod)
	}

	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedDeps | packages.NeedTypes |
			packages.NeedSyntax | packages.NeedTypesInfo | packages.NeedModule,
		Tests:      !c.ignoreTests,
		BuildFlags: buildFlags,
	}
	pkgs, err := packages.Load(cfg, patterns...)
	if err != nil {
		return nil, err
	}
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			return nil, fmt.Errorf("errors while loading package %s: %v", pkg, pkg.Errors)
		}
	}

	var all []UncheckedError
	for _, pkg := range pkgs {
		if c.verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkg.PkgPath)
		}
		pc := &packageChecker{checker: c, pkg: pkg, lines: newLineReader()}
		all = append(all, pc.check()...)
	}

	sort.SliceStable(all, func(i, j int) bool {
		return lessPosition(all[i], all[j])
	})
	// Adjacent de-duplication after sorting.
	out := all[:0]
	var prev *UncheckedError
	for i := range all {
		if prev != nil && prev.Pos == all[i].Pos && prev.Line == all[i].Line && prev.FuncName == all[i].FuncName {
			continue
		}
		out = append(out, all[i])
		prev = &out[len(out)-1]
	}
	return out, nil
}

func lessPosition(a, b UncheckedError) bool {
	if a.Pos.Filename != b.Pos.Filename {
		return a.Pos.Filename < b.Pos.Filename
	}
	if a.Pos.Line != b.Pos.Line {
		return a.Pos.Line < b.Pos.Line
	}
	if a.Pos.Column != b.Pos.Column {
		return a.Pos.Column < b.Pos.Column
	}
	if a.Pos.Offset != b.Pos.Offset {
		return a.Pos.Offset < b.Pos.Offset
	}
	if a.FuncName != b.FuncName {
		return a.FuncName < b.FuncName
	}
	return a.Line < b.Line
}

type packageChecker struct {
	checker *Checker
	pkg     *packages.Package
	lines   *lineReader
	errs    []UncheckedError
}

func (pc *packageChecker) check() []UncheckedError {
	if pc.pkg.Syntax == nil || pc.pkg.TypesInfo == nil {
		return nil
	}
	for _, file := range pc.pkg.Syntax {
		if pc.checker.ignoreTests {
			if name := pc.fileName(file); strings.HasSuffix(name, "_test.go") {
				continue
			}
		}
		if pc.checker.ignoreGenerated && ast.IsGenerated(file) {
			continue
		}
		pc.walk(file)
	}
	return pc.errs
}

func (pc *packageChecker) fileName(file *ast.File) string {
	if pc.pkg.Fset == nil {
		return ""
	}
	tf := pc.pkg.Fset.File(file.Pos())
	if tf == nil {
		return ""
	}
	return tf.Name()
}

func (pc *packageChecker) walk(file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			return true
		}
		switch node := n.(type) {
		case *ast.ExprStmt:
			if call, ok := node.X.(*ast.CallExpr); ok {
				pc.checkCall(call, call.Lparen)
			}
		case *ast.GoStmt:
			if node.Call != nil {
				pc.checkCall(node.Call, node.Call.Lparen)
			}
		case *ast.DeferStmt:
			if node.Call != nil {
				pc.checkCall(node.Call, node.Call.Lparen)
			}
		case *ast.AssignStmt:
			if pc.checker.blank {
				lhs := make([]ast.Expr, len(node.Lhs))
				copy(lhs, node.Lhs)
				pc.checkBlank(lhs, node.Rhs)
			}
		case *ast.ValueSpec:
			if pc.checker.blank && len(node.Values) > 0 {
				lhs := make([]ast.Expr, len(node.Names))
				for i, name := range node.Names {
					lhs[i] = name
				}
				pc.checkBlank(lhs, node.Values)
			}
		case *ast.TypeAssertExpr:
			if pc.checker.asserts {
				pc.checkAssert(node)
			}
		}
		return true
	})
}

func (pc *packageChecker) checkAssert(assert *ast.TypeAssertExpr) {
	if assert.Type == nil {
		return
	}
	if tv, ok := pc.pkg.TypesInfo.Types[assert]; ok && tv.HasOk() {
		return
	}
	pc.addError(assert.Pos(), "")
}

func (pc *packageChecker) checkCall(call *ast.CallExpr, pos token.Pos) {
	if !pc.returnsError(call) {
		return
	}
	if pc.isIgnored(call) || pc.isExcluded(call) {
		return
	}
	pc.addError(pos, pc.funcName(call))
}

func (pc *packageChecker) checkBlank(lhs, rhs []ast.Expr) {
	isBlank := func(e ast.Expr) (token.Pos, bool) {
		if id, ok := e.(*ast.Ident); ok && id.Name == "_" {
			return id.Pos(), true
		}
		return token.NoPos, false
	}
	if len(rhs) == 1 {
		call, ok := rhs[0].(*ast.CallExpr)
		if !ok {
			return
		}
		results := pc.resultTypes(call)
		for i, lh := range lhs {
			pos, blank := isBlank(lh)
			if !blank || i >= len(results) {
				continue
			}
			if !isErrorType(results[i]) {
				continue
			}
			if pc.isIgnored(call) || pc.isExcluded(call) {
				return
			}
			pc.addError(pos, pc.funcName(call))
		}
		return
	}
	if len(lhs) != len(rhs) {
		return
	}
	for i, lh := range lhs {
		pos, blank := isBlank(lh)
		if !blank {
			continue
		}
		call, ok := rhs[i].(*ast.CallExpr)
		if !ok {
			continue
		}
		results := pc.resultTypes(call)
		for _, t := range results {
			if isErrorType(t) {
				if pc.isIgnored(call) || pc.isExcluded(call) {
					break
				}
				pc.addError(pos, pc.funcName(call))
				break
			}
		}
	}
}

func (pc *packageChecker) addError(pos token.Pos, funcName string) {
	position := pc.pkg.Fset.Position(pos)
	if !pc.checker.abspath && filepath.IsAbs(position.Filename) {
		if rel, err := filepath.Rel(pc.checker.cwd, position.Filename); err == nil {
			position.Filename = rel
		}
	}
	line := pc.lines.line(position.Filename, position.Line)
	pc.errs = append(pc.errs, UncheckedError{Pos: position, Line: line, FuncName: funcName})
}

func (pc *packageChecker) returnsError(call *ast.CallExpr) bool {
	for _, t := range pc.resultTypes(call) {
		if isErrorType(t) {
			return true
		}
	}
	return false
}

func (pc *packageChecker) resultTypes(call *ast.CallExpr) []types.Type {
	if pc.pkg.TypesInfo == nil {
		return nil
	}
	t := pc.pkg.TypesInfo.TypeOf(call)
	if t == nil {
		return nil
	}
	if tuple, ok := t.(*types.Tuple); ok {
		result := make([]types.Type, tuple.Len())
		for i := 0; i < tuple.Len(); i++ {
			result[i] = tuple.At(i).Type()
		}
		return result
	}
	return []types.Type{t}
}

func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	return types.Implements(t, errorInterface)
}

func (pc *packageChecker) funcName(call *ast.CallExpr) string {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	if pc.pkg.TypesInfo == nil {
		return ""
	}
	obj := pc.pkg.TypesInfo.ObjectOf(sel.Sel)
	fn, ok := obj.(*types.Func)
	if !ok {
		return ""
	}
	return fn.FullName()
}

// calledIdentity returns the package path and name used by the
// deprecated -ignore/-ignorepkg mechanisms.
func (pc *packageChecker) calledIdentity(call *ast.CallExpr) (string, string, bool) {
	if pc.pkg.TypesInfo == nil {
		return "", "", false
	}
	switch fun := call.Fun.(type) {
	case *ast.SelectorExpr:
		obj := pc.pkg.TypesInfo.ObjectOf(fun.Sel)
		if obj == nil {
			return "", "", false
		}
		pkgPath := ""
		if obj.Pkg() != nil {
			pkgPath = obj.Pkg().Path()
		}
		return pkgPath, fun.Sel.Name, true
	case *ast.Ident:
		obj := pc.pkg.TypesInfo.ObjectOf(fun)
		if obj == nil {
			return "", "", false
		}
		pkgPath := ""
		if obj.Pkg() != nil {
			pkgPath = obj.Pkg().Path()
		}
		return pkgPath, fun.Name, true
	}
	return "", "", false
}

func (pc *packageChecker) ignorePkgSet() map[string]bool {
	if pc.checker.ignorePk != nil {
		return pc.checker.ignorePk
	}
	set := make(map[string]bool)
	if pc.checker.ignorePkg != "" {
		for _, pkg := range strings.Split(pc.checker.ignorePkg, ",") {
			if pkg != "" {
				set[pkg] = true
			}
		}
	}
	pc.checker.ignorePk = set
	return set
}

func (pc *packageChecker) isIgnored(call *ast.CallExpr) bool {
	pkgPath, name, ok := pc.calledIdentity(call)
	if !ok {
		return false
	}
	if pc.ignorePkgSet()[pkgPath] {
		return true
	}
	ignore := pc.checker.ignore
	if ignore == nil {
		return false
	}
	if re, ok := ignore[pkgPath]; ok && re != nil && re.MatchString(name) {
		return true
	}
	if re, ok := ignore[""]; ok && re != nil && re.MatchString(name) {
		return true
	}
	return false
}

func (pc *packageChecker) isExcluded(call *ast.CallExpr) bool {
	name := pc.funcName(call)
	if name == "" {
		return false
	}
	candidates := map[string]bool{name: true}
	pc.addSelectorCandidates(call, candidates)
	for candidate := range candidates {
		if pc.checker.excluded[candidate] {
			return true
		}
	}
	if len(call.Args) == 0 {
		return false
	}
	desc := pc.firstArgDescription(call.Args[0])
	if desc == "" {
		return false
	}
	for candidate := range candidates {
		if pc.checker.excluded[candidate+"("+desc+")"] {
			return true
		}
	}
	return false
}

func (pc *packageChecker) addSelectorCandidates(call *ast.CallExpr, candidates map[string]bool) {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || pc.pkg.TypesInfo == nil {
		return
	}
	obj := pc.pkg.TypesInfo.ObjectOf(sel.Sel)
	if _, ok := obj.(*types.Func); !ok {
		return
	}
	selection, ok := pc.pkg.TypesInfo.Selections[sel]
	if !ok || selection == nil {
		return
	}
	host := pc.selectionHost(sel, selection)
	if host == nil {
		return
	}
	seen := make(map[string]bool)
	pc.collectInterfaceCandidates(host, sel.Sel.Name, candidates, seen)
}

func (pc *packageChecker) selectionHost(sel *ast.SelectorExpr, selection *types.Selection) types.Type {
	t := pc.pkg.TypesInfo.TypeOf(sel.X)
	if t == nil {
		return nil
	}
	indices := selection.Index()
	if len(indices) == 0 {
		return nil
	}
	for _, index := range indices[:len(indices)-1] {
		if ptr, ok := t.(*types.Pointer); ok {
			t = ptr.Elem()
		}
		st, ok := t.Underlying().(*types.Struct)
		if !ok || index < 0 || index >= st.NumFields() {
			return nil
		}
		t = st.Field(index).Type()
	}
	return t
}

func pathQualifier(p *types.Package) string {
	if p == nil {
		return ""
	}
	return p.Path()
}

func (pc *packageChecker) collectInterfaceCandidates(t types.Type, method string, candidates map[string]bool, seen map[string]bool) {
	if t == nil {
		return
	}
	key := types.TypeString(t, pathQualifier)
	if seen[key] {
		return
	}
	seen[key] = true

	switch typ := t.(type) {
	case *types.Named:
		iface, ok := typ.Underlying().(*types.Interface)
		if !ok {
			pc.collectUnderlyingCandidates(typ.Underlying(), method, candidates, seen)
			return
		}
		candidates["("+key+")."+method] = true
		for i := 0; i < iface.NumEmbeddeds(); i++ {
			pc.collectInterfaceCandidates(iface.EmbeddedType(i), method, candidates, seen)
		}
	case *types.Interface:
		candidates["("+key+")."+method] = true
		for i := 0; i < typ.NumEmbeddeds(); i++ {
			pc.collectInterfaceCandidates(typ.EmbeddedType(i), method, candidates, seen)
		}
	case *types.Pointer:
		pc.collectInterfaceCandidates(typ.Elem(), method, candidates, seen)
	case *types.Struct:
		for i := 0; i < typ.NumFields(); i++ {
			field := typ.Field(i)
			if field.Embedded() {
				pc.collectInterfaceCandidates(field.Type(), method, candidates, seen)
			}
		}
	case *types.Alias:
		pc.collectUnderlyingCandidates(typ.Underlying(), method, candidates, seen)
	}
}

func (pc *packageChecker) collectUnderlyingCandidates(t types.Type, method string, candidates map[string]bool, seen map[string]bool) {
	switch typ := t.(type) {
	case *types.Interface:
		for i := 0; i < typ.NumEmbeddeds(); i++ {
			pc.collectInterfaceCandidates(typ.EmbeddedType(i), method, candidates, seen)
		}
	case *types.Struct:
		for i := 0; i < typ.NumFields(); i++ {
			field := typ.Field(i)
			if field.Embedded() {
				pc.collectInterfaceCandidates(field.Type(), method, candidates, seen)
			}
		}
	case *types.Pointer:
		pc.collectInterfaceCandidates(typ.Elem(), method, candidates, seen)
	}
}

func (pc *packageChecker) firstArgDescription(expr ast.Expr) string {
	if pc.pkg.TypesInfo != nil {
		if sel, ok := expr.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok {
				if pkgName, ok := pc.pkg.TypesInfo.ObjectOf(id).(*types.PkgName); ok {
					if imported := pkgName.Imported(); imported != nil && imported.Path() == "os" {
						if sel.Sel.Name == "Stdout" || sel.Sel.Name == "Stderr" {
							return "os." + sel.Sel.Name
						}
					}
				}
			}
		}
	}
	if pc.pkg.TypesInfo == nil {
		return ""
	}
	t := pc.pkg.TypesInfo.TypeOf(expr)
	if t == nil {
		return ""
	}
	return types.TypeString(t, pathQualifier)
}

// lineReader returns source lines, giving "??" when a line cannot be
// read (for example because it came from a //line directive or is
// longer than a scanner token).
type lineReader struct {
	files map[string]*cachedLines
}

type cachedLines struct {
	lines []string
}

func newLineReader() *lineReader {
	return &lineReader{files: make(map[string]*cachedLines)}
}

func (r *lineReader) line(filename string, lineNumber int) string {
	if lineNumber < 1 {
		return "??"
	}
	cached, ok := r.files[filename]
	if !ok {
		cached = &cachedLines{}
		r.files[filename] = cached
		file, err := os.Open(filename)
		if err == nil {
			scanner := bufio.NewScanner(file)
			for scanner.Scan() {
				cached.lines = append(cached.lines, scanner.Text())
			}
			file.Close()
		}
	}
	if lineNumber > len(cached.lines) {
		return "??"
	}
	return strings.TrimSpace(cached.lines[lineNumber-1])
}
