 if p == nil { return "" }
 return aliasFor(p)
}
// check accessible: returns true if type can be referenced from another package
func accessible(t types.Type, seen map[types.Type]bool) bool {
 if t == nil { return true }
 if seen[t] { return true }
 seen[t]=true
 switch x:=t.(type) {
 case *types.Basic: return true
 case *types.Named:
   o:=x.Obj(); if o==nil {return true}
   if o.Pkg()!=nil && !o.Exported() { return false }
   if x.TypeArgs()!=nil { for i:=0;i<x.TypeArgs().Len();i++ { if !accessible(x.TypeArgs().At(i),seen){return false} } }
   return true
 case *types.Alias:
   o:=x.Obj(); if o!=nil && o.Pkg()!=nil && !o.Exported() { return false }
   return accessible(x.Rhs(),seen)
 case *types.Pointer: return accessible(x.Elem(),seen)
 case *types.Slice: return accessible(x.Elem(),seen)
 case *types.Array: return accessible(x.Elem(),seen)
 case *types.Map: return accessible(x.Key(),seen)&&accessible(x.Elem(),seen)
 case *types.Chan: return accessible(x.Elem(),seen)
 case *types.Signature:
   // params/results only regarding type names; unexported field names ok indirect? Named checked
   for _,collection := range []*types.Tuple{x.Params(),x.Results()} { for i:=0;i<collection.Len();i++ { if !accessible(collection.At(i).Type(),seen){return false} } }
   return true
 case *types.Struct:
   for i:=0;i<x.NumFields();i++ { if !accessible(x.Field(i).Type(),seen){return false} }
   return true
 case *types.Interface:
   for i:=0;i<x.NumMethods();i++ { if !accessible(x.Method(i).Type(),seen){return false} }
   for i:=0;i<x.NumEmbeddeds();i++ { if !accessible(x.EmbeddedType(i),seen){return false} }
   return true
 case *types.TypeParam: return false
 }
 return true
