 if len(os.Args)<2 {panic("pkg")}
 pkg,err:=imp.Import(os.Args[1]); if err!=nil {panic(err)}
 if len(os.Args)>2 && os.Args[2]=="list" {
   fmt.Println("FUNCS")
   names:=pkg.Scope().Names(); sort.Strings(names)
   for _,n:=range names { o:=pkg.Scope().Lookup(n); if fn,ok:=o.(*types.Func); ok { sig:=fn.Type().(*types.Signature); if returnsErr(sig){fmt.Println(" ",fn.FullName(), types.TypeString(sig,nil), "generic",sig.TypeParams().Len())} } }
   fmt.Println("TYPES/METHODS")
   for _,n:=range names { o:=pkg.Scope().Lookup(n); tn,ok:=o.(*types.TypeName); if !ok{continue}; named,ok:=tn.Type().(*types.Named); if !ok{continue}; ms:=types.NewMethodSet(types.NewPointer(named)); for i:=0;i<ms.Len();i++ { fn:=ms.At(i).Obj().(*types.Func); sig:=fn.Type().(*types.Signature); if returnsErr(sig){fmt.Println(" ",tn.Name(), fn.FullName(), "exported",fn.Exported())} } }
   return
 }
 var stmts []stmt
 // functions
 names:=pkg.Scope().Names(); sort.Strings(names)
 targetAlias:=aliasFor(pkg)
 for _,n:=range names {
   o:=pkg.Scope().Lookup(n); fn,ok:=o.(*types.Func); if !ok||!fn.Exported(){continue}
   sig:=fn.Type().(*types.Signature); if !returnsErr(sig)||sig.TypeParams().Len()>0 {continue}
   // args
