   for i:=0;i<sig.Params().Len();i++ { v:=sig.Params().At(i); if !accessible(v.Type(),map[types.Type]bool{}){ok=false;break}; vn:=fmt.Sprintf("a_%s_%d",fn.Name(),i); decls=append(decls, fmt.Sprintf("\tvar %s %s",vn,types.TypeString(v.Type(),qualifier))); arg:=vn; if sig.Variadic() && i==sig.Params().Len()-1 {arg+="..."}; args=append(args,arg)}
   if !ok{continue}
   stmts=append(stmts, stmt{strings.Join(decls,"\n"),"decl "+fn.FullName()})
   code:=fmt.Sprintf("\t%s.%s(%s)",targetAlias,fn.Name(),strings.Join(args,", "))
   stmts=append(stmts, stmt{code, fn.FullName()})
 }
 // methods
 for _,n:=range names {
   o:=pkg.Scope().Lookup(n); tn,ok:=o.(*types.TypeName); if !ok||tn.IsAlias()||!tn.Exported(){continue}
   named,ok:=tn.Type().(*types.Named); if !ok||named.TypeParams().Len()>0{continue}
   isIface:= false; if _,ok:=named.Underlying().(*types.Interface); ok {isIface=true}
   var ms *types.MethodSet; var recvDecl string; recvName:=fmt.Sprintf("r_%s",tn.Name())
   if isIface { ms=types.NewMethodSet(named); recvDecl=fmt.Sprintf("\tvar %s %s.%s",recvName,targetAlias,tn.Name()) } else { ms=types.NewMethodSet(types.NewPointer(named)); recvDecl=fmt.Sprintf("\tvar %s *%s.%s",recvName,targetAlias,tn.Name()) }
   stmts=append(stmts, stmt{recvDecl, "recv "+tn.Name()})
   idxs:=make([]int,ms.Len()); for i:=range idxs{idxs[i]=i}; sort.Slice(idxs,func(a,b int)bool{return ms.At(idxs[a]).Obj().Name()<ms.At(idxs[b]).Obj().Name()})
   for _,ii:=range idxs { sel:=ms.At(ii); fn:=sel.Obj().(*types.Func); if !fn.Exported(){continue}; sig:=fn.Type().(*types.Signature); if !returnsErr(sig){continue}; var decls []string; var args []string; ok=true; for i:=0;i<sig.Params().Len();i++ { v:=sig.Params().At(i); if !accessible(v.Type(),map[types.Type]bool{}){ok=false;break}; vn:=fmt.Sprintf("m_%s_%s_%d",tn.Name(),fn.Name(),i); decls=append(decls,fmt.Sprintf("\tvar %s %s",vn,types.TypeString(v.Type(),qualifier))); arg:=vn; if sig.Variadic() && i==sig.Params().Len()-1 {arg+="..."}; args=append(args,arg)}; if !ok{continue}; if len(decls)>0{stmts=append(stmts,stmt{strings.Join(decls,"\n"),"decl "+fn.FullName()})}; stmts=append(stmts,stmt{fmt.Sprintf("\t%s.%s(%s)",recvName,fn.Name(),strings.Join(args,", ")), fn.FullName()}) }
 }
 // Build source: package check; Use func
 var b strings.Builder; b.WriteString("package check\n\n")
 // imports placeholder will be filled later after generation because aliases created during stmt gen already; imports var available
 b.WriteString("import (\n"); for _,im:=range imports {b.WriteString(im+"\n")}; b.WriteString(")\n\nfunc Use() {\n")
 line:=strings.Count(b.String(),"\n")+1
 type rec struct{line int; desc string}; var recs []rec
 for _,s:=range stmts { if s.code==""{continue}; // decl code can contain newlines
   // count each physical line separately for decls, but desc only call lines
   for _,ln:=range strings.Split(s.code,"\n") { if strings.HasPrefix(s.desc,"decl")||strings.HasPrefix(s.desc,"recv") { b.WriteString(ln+"\n"); line++ } else { b.WriteString(ln+"\n"); recs=append(recs,rec{line,s.desc}); line++ } }
 }
 b.WriteString("}\n")
 os.WriteFile("check.go",[]byte(b.String()),0644)
 f,_:=os.Create("manifest.txt"); for _,r:=range recs{fmt.Fprintf(f,"%d %s\n",r.line,r.desc)}; f.Close()
 fmt.Println("wrote",len(recs))
}
